package com.ruoyi.myhealthy.secorder.service;import java.util.List;import org.springframework.stereotype.Service;import com.ruoyi.myhealthy.secorder.domain.SeckillOrder;import com.ruoyi.myhealthy.secorder.mapper.SeckillOrderMapper;import com.ruoyi.common.utils.HealthAccess;import com.ruoyi.common.exception.ServiceException;@Service public class SeckillOrderQueryService{private final SeckillOrderMapper mapper;public SeckillOrderQueryService(SeckillOrderMapper mapper){this.mapper=mapper;}public List<SeckillOrder> list(){if(!HealthAccess.admin())throw new ServiceException("需要管理员权限");return mapper.selectList();}}